import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract_packages(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg['resolvedVersion']
        result[name] = pkgs
    return result

b = extract_packages(baseline)
a = extract_packages(after)
print('BASELINE:')
for p, pkgs in sorted(b.items()):
    print(f'  {p}:')
    for pkg, ver in sorted(pkgs.items()):
        print(f'    {pkg} = {ver}')
print()
print('AFTER:')
for p, pkgs in sorted(a.items()):
    print(f'  {p}:')
    for pkg, ver in sorted(pkgs.items()):
        print(f'    {pkg} = {ver}')
print()
print('CHANGES:')
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg)
        av = ap.get(pkg)
        if bv != av:
            print(f'  {proj}: {pkg} {bv} -> {av}')
